head.script:
scwin.onpageload = function () {
    // Fusionchart 'cht_exam1'의 초기 속성을 설정합니다.
    cht_exam1.setChartAttribute({
        "caption": rad_chartType1.getText(), // radio에 선택된 text를 차트의 caption으로 지정.
        "canvasTopPadding": 6,
        "canvasRightMargin": 10,
        "canvasLeftPadding": 6,
        "canvasRightPadding": 6,
        "chartBottomMargin": 16
    });

    cht_exam2.setChartAttribute({
        "canvasTopPadding": 6,
        "canvasRightMargin": 10,
        "canvasLeftPadding": 6,
        "canvasRightPadding": 6,
        "chartBottomMargin": 16
    });

    let arrPlotColor = ["#2ec6c8", "#FFD700", "#5ab0ee", "#f4984e", "#d77a80", "#90bddc", "#fe5d55", "#b5dc59", "#9ea7b3", "#00ba84", "#878bb6", "#757a85"];

    // Fusionchart 'cht_exam1'의 Plot 배경색을 지정합니다.
    cht_exam1.setPlotColor(arrPlotColor);
    cht_exam2.setPlotColor(arrPlotColor);

    // 지정한 속성을 바탕으로 브라우저에 그립니다.
    cht_exam1.draw();
    cht_exam2.draw();
};

/**
 * 차트 타입이 구성된 Radio 'rad_chartType1'의 이벤트 'onviewchange' 핸들러
 */
scwin.rad_chartType1_onviewchange = function (info) {
    let chartAlias = info.value;
    // Fusionchart 'cht_exam1'의 속성을 설정합니다.
    // radio에 선택된 text를 차트의 caption으로 지정.
    cht_exam1.setChartAttribute({
        "caption": this.getText()
    });

    // Fusionchart 'cht_exam1'의 차트 타입을 변경합니다.
    //cht_exam1.changeType(chartAlias);

    switch (chartAlias) {
        case "stackedcolumn2d":
        case "stackedcolumn3d":
        case "stackedbar2d":
        case "stackedbar3d":
        case "stackedarea2d":
        	cht_exam1.changeType(chartAlias, {ref: "data:dlt_chartData_1", labelNode: "quarter", seriesColumns: "[['type1','type2','type3']]"});
            //cht_exam1.setChartColumnRef("data:dlt_chartData_1", "quarter", "[['type1','type2','type3']]");
            break;
        case "msstackedbar2d":
        case "msstackedcolumn2d":
        	cht_exam1.changeType(chartAlias, {ref: "data:dlt_chartData_1", labelNode: "quarter", seriesColumns: "[['type1','type3'],['type2','type4']]"});
            //cht_exam1.setChartColumnRef("data:dlt_chartData_1", "quarter", "[['type1','type3'],['type2','type4']]");
            break;
        default:
            break;
    }

};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('cht_exam1').innerText != 'No data to display.';
	}		
	scwin.unitTest = function() {
		//noResult="previous"
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('rad_chartType1_input_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "400");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
